# GhostSlice shell completions for bash.
# Generated by `ghostslice completions bash` from the
# live argument parser; do not edit by hand — regenerate.
# Token counts everywhere in GhostSlice output are estimates.

_ghostslice() {
    local cur prev cmd sub
    COMPREPLY=()
    cur="${COMP_WORDS[COMP_CWORD]}"
    prev="${COMP_WORDS[COMP_CWORD-1]}"
    cmd="${COMP_WORDS[1]:-}"
    sub="${COMP_WORDS[2]:-}"
    if [[ ${COMP_CWORD} -eq 1 ]]; then
        COMPREPLY=( $(compgen -W "cache calibrate calls check check-budget ci completions diff doctor explain export graph history init lint mcp prices report scan secrets serve slice symbols task watch" -- "$cur") )
        return 0
    fi
    case "$cmd" in
        cache)
            if [[ ${COMP_CWORD} -eq 2 ]]; then
                COMPREPLY=( $(compgen -W "clear stats -h --help" -- "$cur") )
                return 0
            fi
            case "$sub" in
                clear)
                    COMPREPLY=( $(compgen -W "-h --help" -- "$cur") )
                    return 0
                    ;;
                stats)
                    COMPREPLY=( $(compgen -W "-h --help --json" -- "$cur") )
                    return 0
                    ;;
            esac
            ;;
        calibrate)
            COMPREPLY=( $(compgen -W "-h --help --json" -- "$cur") )
            return 0
            ;;
        calls)
            COMPREPLY=( $(compgen -W "-h --help --json --dead" -- "$cur") )
            return 0
            ;;
        check)
            COMPREPLY=( $(compgen -W "-h --help" -- "$cur") )
            return 0
            ;;
        check-budget)
            COMPREPLY=( $(compgen -W "-h --help --max-tokens --mode" -- "$cur") )
            return 0
            ;;
        ci)
            COMPREPLY=( $(compgen -W "-h --help --budget --strict --allow-secrets --fail-on-secrets --json --pr-comment --out" -- "$cur") )
            return 0
            ;;
        completions)
            COMPREPLY=( $(compgen -W "-h --help" -- "$cur") )
            return 0
            ;;
        diff)
            COMPREPLY=( $(compgen -W "-h --help --json" -- "$cur") )
            return 0
            ;;
        doctor)
            COMPREPLY=( $(compgen -W "-h --help --json" -- "$cur") )
            return 0
            ;;
        explain)
            COMPREPLY=( $(compgen -W "-h --help --mode" -- "$cur") )
            return 0
            ;;
        export)
            COMPREPLY=( $(compgen -W "-h --help -o --out --mode --preset --model --exclude-secrets --redact --no-redact --auto-shrink --fit --symbols --timing --no-cache --workers --plugin --allow-plugin-override" -- "$cur") )
            return 0
            ;;
        graph)
            COMPREPLY=( $(compgen -W "-h --help --json" -- "$cur") )
            return 0
            ;;
        history)
            COMPREPLY=( $(compgen -W "-h --help --json --trend --model" -- "$cur") )
            return 0
            ;;
        init)
            COMPREPLY=( $(compgen -W "-h --help --yes --force --dry-run --budget --model" -- "$cur") )
            return 0
            ;;
        lint)
            COMPREPLY=( $(compgen -W "-h --help --json --strict" -- "$cur") )
            return 0
            ;;
        mcp)
            COMPREPLY=( $(compgen -W "-h --help" -- "$cur") )
            return 0
            ;;
        prices)
            COMPREPLY=( $(compgen -W "-h --help" -- "$cur") )
            return 0
            ;;
        report)
            COMPREPLY=( $(compgen -W "-h --help -o --out --model" -- "$cur") )
            return 0
            ;;
        scan)
            COMPREPLY=( $(compgen -W "-h --help --json --top --model --timing --no-cache" -- "$cur") )
            return 0
            ;;
        secrets)
            COMPREPLY=( $(compgen -W "-h --help --json" -- "$cur") )
            return 0
            ;;
        serve)
            COMPREPLY=( $(compgen -W "-h --help --port --host" -- "$cur") )
            return 0
            ;;
        slice)
            COMPREPLY=( $(compgen -W "-h --help --mode -o --out --no-cache --plugin --allow-plugin-override" -- "$cur") )
            return 0
            ;;
        symbols)
            COMPREPLY=( $(compgen -W "-h --help --json" -- "$cur") )
            return 0
            ;;
        task)
            COMPREPLY=( $(compgen -W "-h --help --task --diff --budget --fit -o --out --preset --model --redact --no-redact --plugin --allow-plugin-override" -- "$cur") )
            return 0
            ;;
        watch)
            COMPREPLY=( $(compgen -W "-h --help -o --out --export --interval --debounce --once --max-events --mode --preset --exclude-secrets --redact --no-redact --auto-shrink --fit --plugin --allow-plugin-override" -- "$cur") )
            return 0
            ;;
    esac
    return 0
}

complete -o default -F _ghostslice ghostslice
# Top-level flags (before the subcommand): -h --help --version
